* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    min-height: 100vh;
    padding: 20px;
    color: #1a202c;
    line-height: 1.6;
}

main {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    background: white;
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
    padding: 40px;
    max-width: 500px;
    width: 100%;
}

h1 {
    font-size: 28px;
    font-weight: 600;
    margin-bottom: 12px;
    color: #1a202c;
}

.intro-text {
    color: #718096;
    margin-bottom: 32px;
    font-size: 16px;
}

form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

label {
    font-weight: 500;
    font-size: 14px;
    color: #2d3748;
    display: block;
}

label span {
    color: #e53e3e;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 10px 12px;
    border: 2px solid #cbd5e0;
    border-radius: 6px;
    font-size: 16px;
    font-family: inherit;
    transition: border-color 0.2s, box-shadow 0.2s;
    background-color: white;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
    outline: none;
    border-color: #3182ce;
    box-shadow: 0 0 0 3px rgba(49, 130, 206, 0.1);
}

input[type="text"]:disabled,
input[type="email"]:disabled,
input[type="tel"]:disabled {
    background-color: #f7fafc;
    color: #a0aec0;
    cursor: not-allowed;
}

/* Invalid state */
input[aria-invalid="true"] {
    border-color: #e53e3e;
}

input[aria-invalid="true"]:focus {
    box-shadow: 0 0 0 3px rgba(229, 62, 62, 0.1);
}

.help-text {
    font-size: 13px;
    color: #718096;
    margin: 0;
}

.error-text {
    font-size: 13px;
    color: #e53e3e;
    margin: 0;
    display: none;
}

.error-text.show {
    display: block;
}

.submit-button {
    padding: 12px 24px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
    margin-top: 8px;
}

.submit-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(102, 126, 234, 0.4);
}

.submit-button:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.5);
}

.submit-button:active {
    transform: translateY(0);
}

.submit-button:disabled {
    background: #cbd5e0;
    cursor: not-allowed;
    transform: none;
}

/* Responsive design */
@media (max-width: 600px) {
    .container {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    .intro-text {
        font-size: 14px;
    }

    body {
        padding: 16px;
    }
}

/* Forced Colors Mode (High Contrast) */
@media (forced-colors: active) {
    input[type="text"],
    input[type="email"],
    input[type="tel"] {
        border: 2px solid CanvasText;
        background-color: Canvas;
        color: CanvasText;
    }

    input[type="text"]:focus,
    input[type="email"]:focus,
    input[type="tel"]:focus {
        outline: 2px solid Highlight;
    }

    .submit-button {
        background-color: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
        forced-color-adjust: none;
    }

    .submit-button:focus {
        outline: 2px solid Highlight;
    }
}

/* Prefers reduced motion */
@media (prefers-reduced-motion: reduce) {
    input[type="text"],
    input[type="email"],
    input[type="tel"],
    .submit-button {
        transition: none;
    }
}
