            isValid = false;
            errorMessage = errorMessages[fieldName]?.valueMissing || 'Error: This field is required.';
        } else if (field.type === 'email' && field.value !== '') {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(field.value)) {
                isValid = false;
                errorMessage = errorMessages[fieldName]?.typeMismatch || 'Error: Enter a valid email.';
            }
        } else if (field.type === 'tel' && field.value !== '') {
