    const form = document.getElementById('contactForm');
    const fullNameInput = document.getElementById('fullName');
    const emailInput = document.getElementById('email');
    const phoneInput = document.getElementById('phone');

    const errorMessages = {
        fullName: {
            valueMissing: 'Error: Full name is required.',
        },
        email: {
            valueMissing: 'Error: Email address is required.',
            typeMismatch: 'Error: Enter a valid email like name@example.com.',
        },
        phone: {
            typeMismatch: 'Error: Enter a valid phone number.',
        },
    };

    function createErrorElement(fieldName) {
        const errorId = `${fieldName}Error`;
        let errorElement = document.getElementById(errorId);

        if (!errorElement) {
            errorElement = document.createElement('p');
            errorElement.id = errorId;
            errorElement.className = 'error-text';
            const input = document.getElementById(
                fieldName.charAt(0).toUpperCase() + fieldName.slice(1)
            );
            input.parentNode.appendChild(errorElement);
        }

        return errorElement;
    }

    function validateField(field) {
        const fieldName = field.id.replace(/([A-Z])/g, (match) => match.toLowerCase());
        const errorElement = createErrorElement(fieldName);
        let isValid = true;
        let errorMessage = '';

        if (field.required && field.value.trim() === '') {
            isValid = false;
            errorMessage = errorMessages[fieldName]?.valueMissing || 'Error: This field is required.';
        } else if (field.type === 'email' && field.value !== '') {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(field.value)) {
                isValid = false;
                errorMessage = errorMessages[fieldName]?.typeMismatch || 'Error: Enter a valid email.';
            }
        } else if (field.type === 'tel' && field.value !== '') {
            const phoneRegex = /^[\d\s\-()+]+$/;
            if (!phoneRegex.test(field.value) || field.value.replace(/\D/g, '').length < 10) {
                isValid = false;
                errorMessage = errorMessages[fieldName]?.typeMismatch || 'Error: Enter a valid phone number.';
            }
        }

        field.setAttribute('aria-invalid', !isValid);

        if (!isValid) {
            errorElement.textContent = errorMessage;
            errorElement.classList.add('show');
            const currentDescribedBy = field.getAttribute('aria-describedby') || '';
            const errorId = errorElement.id;
            if (!currentDescribedBy.includes(errorId)) {
                field.setAttribute('aria-describedby', `${currentDescribedBy} ${errorId}`.trim());
            }
        } else {
            errorElement.classList.remove('show');
            const currentDescribedBy = field.getAttribute('aria-describedby') || '';
            const errorId = errorElement.id;
            const newDescribedBy = currentDescribedBy
                .split(' ')
                .filter((id) => id !== errorId)
                .join(' ')
                .trim();
            if (newDescribedBy) {
                field.setAttribute('aria-describedby', newDescribedBy);
            } else {
                field.removeAttribute('aria-describedby');
            }
        }

        return isValid;
    }

    fullNameInput.addEventListener('blur', () => validateField(fullNameInput));
    emailInput.addEventListener('blur', () => validateField(emailInput));
    phoneInput.addEventListener('blur', () => validateField(phoneInput));

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const isFullNameValid = validateField(fullNameInput);
        const isEmailValid = validateField(emailInput);
        const isPhoneValid = validateField(phoneInput);

        if (isFullNameValid && isEmailValid && isPhoneValid) {
            const formData = {
                fullName: fullNameInput.value.trim(),
                email: emailInput.value.trim(),
                phone: phoneInput.value.trim() || 'Not provided',
            };

            console.log('Form submitted successfully:', formData);
            alert('Thank you! Your message has been received. We will get back to you soon.');
            form.reset();
            fullNameInput.removeAttribute('aria-invalid');
            emailInput.removeAttribute('aria-invalid');
            phoneInput.removeAttribute('aria-invalid');
            document.querySelectorAll('.error-text').forEach((el) => el.classList.remove('show'));
            document.querySelectorAll('input[type="text"], input[type="email"], input[type="tel"]').forEach((el) => {
                el.removeAttribute('aria-describedby');
                el.setAttribute('aria-describedby', 'phoneHelp');
            });
            phoneInput.setAttribute('aria-describedby', 'phoneHelp');
        } else {
            const firstInvalidField = [fullNameInput, emailInput, phoneInput].find(
                (field) => field.getAttribute('aria-invalid') === 'true'
            );
            if (firstInvalidField) {
                firstInvalidField.focus();
            }
        }
    });
});
