         color: ButtonText;
         border: 1px solid ButtonBorder;
         forced-color-adjust: none;
     }

     .submit-button:focus {
         outline: 2px solid Highlight;
     }
 }

 /* Prefers reduced motion */
 @media (prefers-reduced-motion: reduce) {
     input[type="text"],
     input[type="email"],
     input[type="tel"],
     .submit-button {
         transition: none;
